INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6748432, 1010654, 76335, '<td valign="top">A masterpiece!</td>', 'A masterpiece!', '2012-04-21 21:35:31.000000', NULL, 1),
(6748433, 1010719, 76335, '<td valign="top">A lesson in framing. Seriously. I learn something from photographs like this.</td>', 'A lesson in framing. Seriously. I learn something from photographs like this.', '2012-04-21 21:36:18.000000', NULL, 1),
(6748434, 1010665, 76335, '<td valign="top">Great combination of elements.</td>', 'Great combination of elements.', '2012-04-21 21:37:29.000000', NULL, 1),
(6748435, 1010626, 76335, '<td valign="top">Unresolved and unsettling. Good.</td>', 'Unresolved and unsettling. Good.', '2012-04-21 21:37:51.000000', NULL, 1),
(6748597, 1010547, 118154, '<td valign="top">I really like this image.</td>', 'I really like this image.', '2012-04-22 07:35:19.000000', NULL, 1),
(6748598, 1010719, 118154, '<td valign="top">Good work.</td>', 'Good work.', '2012-04-22 07:35:54.000000', NULL, 1),
(6748599, 1009938, 118154, '<td valign="top">They look so mean,which makes it work the way intended.</td>', 'They look so mean,which makes it work the way intended.', '2012-04-22 07:36:59.000000', NULL, 1),
(6748600, 1009826, 118154, '<td valign="top">Very nice shot, perfect for the challenge.</td>', 'Very nice shot, perfect for the challenge.', '2012-04-22 07:37:56.000000', NULL, 1),
(6748610, 1009959, 146361, '<td valign="top">I would have liked a little less highlights on the subject (i.e. the itty bitty drooler) to get a little bit more contrast between baby and background</td>', 'I would have liked a little less highlights on the subject (i.e. the itty bitty drooler) to get a little bit more contrast between baby and background', '2012-04-22 08:42:26.000000', NULL, 1),
(6748612, 1010732, 146361, '<td valign="top">Nicely timed shot. The people on the bridge are even nicely spread out. I do get the feeling bringing the highlights down a little might improve the overall picture.</td>', 'Nicely timed shot. The people on the bridge are even nicely spread out. I do get the feeling bringing the highlights down a little might improve the overall picture.', '2012-04-22 08:44:38.000000', NULL, 1),
(6748613, 1010537, 146361, '<td valign="top">Love the feeling this picture invokes. I would ask where it was taken, but it''s probably on the other side of the world for me anyway :-)</td>', 'Love the feeling this picture invokes. I would ask where it was taken, but it''s probably on the other side of the world for me anyway :-)', '2012-04-22 08:45:56.000000', NULL, 1),
(6748615, 1010601, 146361, '<td valign="top">I like the idea, but I get the feeling that there might have been an even better angle available. The inside details in the lower left distract a little, leading me to look at the opposite top right, where I miss the corner of the window.</td>', 'I like the idea, but I get the feeling that there might have been an even better angle available. The inside details in the lower left distract a little, leading me to look at the opposite top right, where I miss the corner of the window.', '2012-04-22 08:49:04.000000', NULL, 1),
(6748616, 1010142, 146361, '<td valign="top">Great reflection &amp; symmetry, took me a little time to decipher what I was actually seeing. I do get the feeling that a little more contrasts might have improved the image however.<br/><br/><i>Message edited by author 2012-04-25 01:38:57.</i></td>', 'Great reflection & symmetry, took me a little time to decipher what I was actually seeing. I do get the feeling that a little more contrasts might have improved the image however.', '2012-04-22 08:52:17.000000', '2012-04-25 02:38:57.000000', 1),
(6748624, 1010626, 146361, '<td valign="top">The chosen focus keeps me wondering what the idea was behind the shallow DOF...</td>', 'The chosen focus keeps me wondering what the idea was behind the shallow DOF...', '2012-04-22 09:27:11.000000', NULL, 1),
(6748626, 1010738, 146361, '<td valign="top">Lovely idea and great colors (of course with this subject). I do wonder however if the picture might have looked better if the camera was aimed slightly higher, removing the large (almost) empty area at the bottom of the image.</td>', 'Lovely idea and great colors (of course with this subject). I do wonder however if the picture might have looked better if the camera was aimed slightly higher, removing the large (almost) empty area at the bottom of the image.', '2012-04-22 09:29:03.000000', NULL, 1),
(6748627, 1010652, 146361, '<td valign="top">I have a problem with the framing concept here?</td>', 'I have a problem with the framing concept here?', '2012-04-22 09:31:37.000000', NULL, 1),
(6748628, 1009817, 146361, '<td valign="top">Lovely idea. I do wonder if a color version might have been better however (unless it''s a black horse ofcourse...)</td>', 'Lovely idea. I do wonder if a color version might have been better however (unless it''s a black horse ofcourse...)', '2012-04-22 09:32:29.000000', NULL, 1),
(6748630, 1010609, 146361, '<td valign="top">Love the way that the framing seems to follow the lines of the subject.</td>', 'Love the way that the framing seems to follow the lines of the subject.', '2012-04-22 09:33:03.000000', NULL, 1),
(6748631, 1010694, 146361, '<td valign="top">A bit of a yes-and-no picture. The color of the bird blends to much with the leaves for my taste (i.e. ''no''). Once you know the bird is there however, your eye keeps getting drawn to it (i.e. ''yes'')</td>', 'A bit of a yes-and-no picture. The color of the bird blends to much with the leaves for my taste (i.e. ''no''). Once you know the bird is there however, your eye keeps getting drawn to it (i.e. ''yes'')', '2012-04-22 09:35:34.000000', NULL, 1),
(6748632, 1009466, 146361, '<td valign="top">I would like to see this a version of this picture with a less shallow depth of field, just to know which one I would like better. Right now, I can''t make up my mind about that...</td>', 'I would like to see this a version of this picture with a less shallow depth of field, just to know which one I would like better. Right now, I can''t make up my mind about that...', '2012-04-22 09:36:34.000000', NULL, 1),
(6748633, 1010731, 146361, '<td valign="top">Thought I see the ''Modeled'' part, I''m left wondering about the ''Frame'' part?</td>', 'Thought I see the ''Modeled'' part, I''m left wondering about the ''Frame'' part?', '2012-04-22 09:37:20.000000', NULL, 1),
(6748634, 1010583, 146361, '<td valign="top">Is the idea that the animal is in the frame of the camera on the opposite?<br/> <br/>If so: nice interpretation. Though I do wonder if a less shallow depth of field to bring the other camera more in focus might not have been a better idea.<br/> <br/>Otherwise: I should lower the score I gave, unless I''m missing something in the picture :-)</td>', 'Is the idea that the animal is in the frame of the camera on the opposite? If so: nice interpretation. Though I do wonder if a less shallow depth of field to bring the other camera more in focus might not have been a better idea. Otherwise: I should lower the score I gave, unless I''m missing something in the picture :-)', '2012-04-22 09:41:01.000000', NULL, 1),
(6748636, 1010537, 14001, '<td valign="top">Very nice HDR shot, and nice use of sepia, definitely a ribbon.  Oh, meets the challenge well too!!</td>', 'Very nice HDR shot, and nice use of sepia, definitely a ribbon.  Oh, meets the challenge well too!!', '2012-04-22 09:42:00.000000', NULL, 1),
(6748637, 1010142, 14001, '<td valign="top">Very interesting!  Like the creativity,</td>', 'Very interesting!  Like the creativity,', '2012-04-22 09:42:23.000000', NULL, 1),
